import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·5","description":"易小帖 - 卷三·5","frontmatter":{"title":"卷三·5","description":"易小帖 - 卷三·5"},"headers":[],"relativePath":"zh/classics/yixiaotie/073.md","filePath":"zh/classics/yixiaotie/073.md"}'),o={name:"zh/classics/yixiaotie/073.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·5",tabindex:"-1"},[r("卷三·5 "),e("a",{class:"header-anchor",href:"#卷三·5","aria-label":"Permalink to “卷三·5”"},"​")],-1),e("p",null,"仲氏曰：唐後儒不曉取象，然動輒曰象。如小畜一卦，頗難解說，而《本義》以象字了之，於「密雲不雨，自我西郊」曰：「故有密雲不雨自我西郊之象。」「復自道」曰：「故有進復自道之象。」「輿說輻」曰：「故有輿說輻之象。」「夫妻反目」曰：「又有夫妻反目之象。」「有孚血去惕出」曰：「是有孚而血去惕出之象。」「有孚攣如富以其隣」曰：「故為有孚攣固用富厚之力而以其隣之象。」「既雨既處」曰：「故為既雨既處之象。」如此則凡上下經六十四卦，祗用此一語了之足矣，何必又註也。初讀小畜至密雲二語，頗不能解。及讀小過九五復有此二句，而重疑之。間考輔嗣註，則第雲：「陽上薄陰，陰不能固陽，故不雨。」夫以一陰而內外皆陽，何曾上薄？以五陽而為一陰所畜，何曾不固？且不固不雨，不必西郊也。縱有西郊，亦不必雲自我也。及觀《推易》，則無絲毫可假借者。夫以坎之為水也，其未成為水，則稱雨，如曰「雷雨之動滿盈」是也。未為雨則又稱雲，如曰「雲雷屯」是也，故猶是坎水而不成坎，則不成水。不成水則並不成雨，此辭例有然者。今小畜一陰從姤夬來，夬之上兌，上半坎也。姤之下巽，下半坎也，乃以兩半坎合之，而成小畜。其在一陰，則仍當兩半坎之間，此非密雲乎？不成坎則不成雨，非不雨乎？推之小過，則上震一陽，下艮一陽，震為上半坎，而艮為下半坎，與夬姤同，乃合之而成小過。其在二陽則仍當兩半坎之間，與小畜同，此天然比合者，而況兌為西郊。小畜小過，皆有互兌，而小畜陰主之，小過陽主之，則其所為西郊者，皆稱自我，無可易也。所謂易有五易，而實不易者此也。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
